use vstd::prelude::*;

verus! {

/// Specification: the result sequence contains, at each index i,
/// the last element of the i-th inner sequence.
spec fn rear_chars_spec(l: Seq<Seq<char>>) -> Seq<char>
    decreases l.len(),
{
    Seq::<char>::new(l.len(), |i: int| l[i].last())
}

fn extract_rear_chars(l: &Vec<Vec<char>>) -> (r: Vec<char>)
    requires
        // Every inner vector is non-empty
        forall|i: int| 0 <= i < l@.len() ==> l@[i].len() > 0,
    ensures
        // Length condition
        r@.len() == l@.len(),
        // Pointwise last-character condition
        forall|i: int|
            0 <= i < l@.len() ==> r@[i] == l@[i][l@[i].len() - 1],
{
    let mut r: Vec<char> = Vec::new();
    let mut i: usize = 0;

    while i < l.len()
        invariant
            i <= l@.len(),
            // maintain the precondition fact in the loop
            forall|j: int| 0 <= j < l@.len() ==> l@[j].len() > 0,
            // r has exactly i collected characters so far
            r@.len() == i as int,
            // each collected character is the last of the corresponding inner vector
            forall|j: int|
                0 <= j < i as int ==> r@[j] == l@[j][l@[j].len() - 1],
        decreases l.len() - i,
    {
        // Show current inner vector is non-empty, so indexing at len-1 is safe.
        assert(l@[i as int].len() > 0);

        let inner = &l[i];
        let last_index: usize = inner.len() - 1;
        let c: char = inner[last_index];
        r.push(c);

        i = i + 1;
    }

    r
}

} // verus!

